// SPDX-License-Identifier: GPL-3.0-or-later
//! Full application/persistence/player acceptance across actual OS processes.
//!
//! Karin contributors dedicate the original audio generated by this fixture to
//! the public domain under CC0 1.0: https://creativecommons.org/publicdomain/zero/1.0/.
//! The application uses its ordinary private HTTP cache policy, without an
//! injected license/storage authority. Ownership of this original fixture does
//! not prove any rights or live-service behavior for the Yandex catalog.

use super::*;
use crate::playback::PlaybackSourceKind;
use ring::digest::{SHA256, digest};
use std::{
    fs,
    os::unix::fs::MetadataExt,
    process::{Child, Command, Stdio},
};

const SELECTOR: &str = "ui::music::persistence::tests::app_cache_acceptance::native_audio_cache_application_process_restart";
const TITLE: &str = "Karin HTTP cache acceptance";
const PHASE_ENV: &str = "KARIN_ORIGINAL_CACHE_PHASE";
const INPUT_ENV: &str = "KARIN_ORIGINAL_CACHE_INPUT";

#[derive(Clone, Default, serde::Serialize, serde::Deserialize)]
struct Counts {
    account: u64,
    offers: u64,
    descriptors: u64,
    media_gets: u64,
    native_gets: u64,
    background_gets: u64,
    media_heads: u64,
    media_not_modified: u64,
    media_bytes: u64,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct Input {
    directory: PathBuf,
    origin: String,
    sha256: [u8; 32],
    bytes: u64,
    license: String,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct PhaseReport {
    phase: String,
    pid: u32,
    account_revalidated: bool,
    cache_policy: String,
    first_source: String,
    replay_source: Option<String>,
    clear_kept_playing: bool,
    default_limit_bytes: u64,
}

struct OriginalServer {
    origin: String,
    counts: Arc<Mutex<Counts>>,
    deny: Arc<AtomicBool>,
    no_store: Arc<AtomicBool>,
    get_only_no_store: Arc<AtomicBool>,
    changed: Arc<AtomicBool>,
    etag_revision: Arc<AtomicU64>,
    no_validator: Arc<AtomicBool>,
    timestamp: Arc<AtomicU64>,
    stop: Arc<AtomicBool>,
    handle: Option<thread::JoinHandle<()>>,
}
impl OriginalServer {
    fn new(media: Arc<Vec<u8>>, replacement: Arc<Vec<u8>>) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let origin = format!("http://{}/", listener.local_addr().unwrap());
        let counts = Arc::new(Mutex::new(Counts::default()));
        let deny = Arc::new(AtomicBool::new(false));
        let no_store = Arc::new(AtomicBool::new(false));
        let get_only_no_store = Arc::new(AtomicBool::new(false));
        let changed = Arc::new(AtomicBool::new(false));
        let etag_revision = Arc::new(AtomicU64::new(1));
        let no_validator = Arc::new(AtomicBool::new(false));
        let timestamp = Arc::new(AtomicU64::new(1_700_000_000));
        let stop = Arc::new(AtomicBool::new(false));
        let handle = {
            let counts = counts.clone();
            let deny = deny.clone();
            let no_store = no_store.clone();
            let get_only_no_store = get_only_no_store.clone();
            let changed = changed.clone();
            let etag_revision = etag_revision.clone();
            let no_validator = no_validator.clone();
            let timestamp = timestamp.clone();
            let stop = stop.clone();
            let origin = origin.clone();
            thread::spawn(move || {
                let mut children = Vec::new();
                while !stop.load(Ordering::Acquire) {
                    match listener.accept() {
                        Ok((stream, _)) => {
                            assert!(
                                children.len() < 128,
                                "bounded original-source request count"
                            );
                            let counts = counts.clone();
                            let deny = deny.clone();
                            let no_store = no_store.clone();
                            let get_only_no_store = get_only_no_store.clone();
                            let changed = changed.clone();
                            let etag_revision = etag_revision.clone();
                            let no_validator = no_validator.clone();
                            let timestamp = timestamp.clone();
                            let media = media.clone();
                            let replacement = replacement.clone();
                            let origin = origin.clone();
                            children.push(thread::spawn(move || {
                                let updated = changed.load(Ordering::Acquire);
                                serve_original(
                                    stream,
                                    &origin,
                                    if updated { &replacement } else { &media },
                                    &counts,
                                    &deny,
                                    &no_store,
                                    (
                                        (!no_validator.load(Ordering::Acquire)).then_some(
                                            match etag_revision.load(Ordering::Acquire) {
                                                1 => "\"karin-original-v1\"",
                                                2 => "\"karin-original-v2\"",
                                                3 => "\"karin-original-v3\"",
                                                _ => panic!("unexpected original-source version"),
                                            },
                                        ),
                                        timestamp.load(Ordering::Acquire),
                                        get_only_no_store.load(Ordering::Acquire),
                                    ),
                                )
                            }));
                        }
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            thread::sleep(Duration::from_millis(2))
                        }
                        Err(_) => panic!("original source listener failed"),
                    }
                }
                for child in children {
                    child.join().unwrap();
                }
            })
        };
        Self {
            origin,
            counts,
            deny,
            no_store,
            get_only_no_store,
            changed,
            etag_revision,
            no_validator,
            timestamp,
            stop,
            handle: Some(handle),
        }
    }
    fn counts(&self) -> Counts {
        self.counts.lock().unwrap().clone()
    }
}
impl Drop for OriginalServer {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        self.handle.take().unwrap().join().unwrap();
    }
}

fn serve_original(
    mut stream: TcpStream,
    origin: &str,
    media: &[u8],
    counts: &Mutex<Counts>,
    deny: &AtomicBool,
    no_store: &AtomicBool,
    version: (Option<&str>, u64, bool),
) {
    let (etag, timestamp, get_only_no_store) = version;
    stream
        .set_read_timeout(Some(Duration::from_secs(3)))
        .unwrap();
    stream
        .set_write_timeout(Some(Duration::from_secs(3)))
        .unwrap();
    let mut request = Vec::new();
    let mut byte = [0];
    while !request.ends_with(b"\r\n\r\n") {
        if stream.read(&mut byte).unwrap_or(0) == 0 {
            return;
        }
        request.push(byte[0]);
        assert!(request.len() < 16 * 1024);
    }
    let request = String::from_utf8(request).unwrap();
    let first = request
        .lines()
        .next()
        .unwrap()
        .split_whitespace()
        .collect::<Vec<_>>();
    let url = reqwest::Url::parse(&format!("http://127.0.0.1{}", first[1])).unwrap();
    let header = |name: &str| {
        request.lines().skip(1).find_map(|line| {
            let (key, value) = line.split_once(':')?;
            key.eq_ignore_ascii_case(name).then_some(value.trim())
        })
    };
    let transport =
        url.path().starts_with("/download-info/") || url.path().starts_with("/get-mp3/");
    if transport {
        for forbidden in ["authorization", "cookie", "origin", "referer"] {
            assert!(header(forbidden).is_none());
        }
    } else {
        assert_eq!(
            header("authorization"),
            Some("OAuth synthetic-storage-ui-token")
        );
    }
    if url.path() == "/tracks" {
        assert_eq!(first[0], "POST");
        let length: usize = header("content-length").unwrap().parse().unwrap();
        assert!(length < 128);
        let mut form = vec![0; length];
        stream.read_exact(&mut form).unwrap();
        assert_eq!(form, b"track-ids=42");
    } else {
        assert!(
            matches!(first[0], "GET" | "HEAD"),
            "no startup radio or mutation request"
        );
    }
    let response = match url.path() {
        "/account/status" => {
            counts.lock().unwrap().account += 1;
            json!({"result":{"account":{"uid":1234,"displayName":"Original audio fixture"}}})
        }
        "/users/1234/likes/tracks" => {
            json!({"result":{"library":{"uid":1234,"revision":1,"tracks":[{"id":42}]}}})
        }
        "/users/1234/dislikes/tracks" => {
            json!({"result":{"library":{"uid":1234,"revision":1,"tracks":[]}}})
        }
        "/users/1234/playlists/list" | "/users/1234/likes/playlists" => json!({"result":[]}),
        "/tracks" => {
            json!({"result":[{"id":42,"title":"Original CC0 audio","durationMs":6000,"available":true,"artists":[{"id":7,"name":"Karin test source"}]}]})
        }
        "/tracks/42/download-info" => {
            counts.lock().unwrap().offers += 1;
            if deny.load(Ordering::Acquire) {
                let _ = stream.write_all(
                    b"HTTP/1.1 403 Forbidden\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{}",
                );
                return;
            }
            json!({"result":[{"codec":"mp3","bitrateInKbps":128,"preview":false,"direct":false,"downloadInfoUrl":format!("{origin}download-info/42")} ]})
        }
        "/download-info/42" => {
            counts.lock().unwrap().descriptors += 1;
            // Finite source latency lets the independently bounded local lookup
            // finish; it is not a production wait or a relaxed input deadline.
            thread::sleep(Duration::from_millis(30));
            let body = format!(
                "<download-info><host>s268myt.storage.yandex.net</host><path>/original-cc0.mp3</path><ts>{timestamp}</ts><s>original-fixture-input</s></download-info>"
            );
            write_response(&mut stream, "application/xml", body.as_bytes());
            return;
        }
        path if path.starts_with("/get-mp3/") && path.ends_with("/original-cc0.mp3") => {
            let cache_control =
                if no_store.load(Ordering::Acquire) || (get_only_no_store && first[0] != "HEAD") {
                    "no-store"
                } else {
                    "private, no-cache, must-revalidate"
                };
            if first[0] == "HEAD" {
                counts.lock().unwrap().media_heads += 1;
                if let Some(etag) = etag.filter(|value| header("if-none-match") == Some(*value)) {
                    counts.lock().unwrap().media_not_modified += 1;
                    let _ = write!(
                        stream,
                        "HTTP/1.1 304 Not Modified\r\nContent-Type: audio/mpeg\r\nETag: {}\r\nCache-Control: {cache_control}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        etag,
                        media.len()
                    );
                    return;
                }
            }
            let range = header("range").map(|value| {
                let (start, end) = value
                    .strip_prefix("bytes=")
                    .unwrap()
                    .split_once('-')
                    .unwrap();
                let start = start.parse::<usize>().unwrap();
                let end = if end.is_empty() {
                    media.len() - 1
                } else {
                    end.parse::<usize>().unwrap().min(media.len() - 1)
                };
                assert!(start <= end && end < media.len());
                (start, end)
            });
            let (start, end) = range.unwrap_or((0, media.len() - 1));
            {
                let mut counts = counts.lock().unwrap();
                if first[0] != "HEAD" {
                    counts.media_gets += 1;
                    if header("cache-control") == Some("no-cache") {
                        counts.background_gets += 1;
                    } else {
                        counts.native_gets += 1;
                    }
                    counts.media_bytes += (end - start + 1) as u64;
                }
            }
            let status = if range.is_some() {
                "206 Partial Content"
            } else {
                "200 OK"
            };
            let _ = write!(
                stream,
                "HTTP/1.1 {status}\r\nContent-Type: audio/mpeg\r\nAccept-Ranges: bytes\r\nCache-Control: {cache_control}\r\nContent-Length: {}\r\nConnection: close\r\n",
                end - start + 1
            );
            if let Some(etag) = etag {
                let _ = write!(stream, "ETag: {etag}\r\n");
            }
            if range.is_some() {
                let _ = write!(
                    stream,
                    "Content-Range: bytes {start}-{end}/{}\r\n",
                    media.len()
                );
            }
            let _ = stream.write_all(b"\r\n");
            if first[0] != "HEAD" {
                let _ = stream.write_all(&media[start..=end]);
            }
            return;
        }
        _ => panic!("unexpected original-source route"),
    };
    write_response(
        &mut stream,
        "application/json",
        response.to_string().as_bytes(),
    );
}
fn write_response(stream: &mut TcpStream, content_type: &str, body: &[u8]) {
    let _ = write!(
        stream,
        "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    let _ = stream.write_all(body);
}

fn permitted_audio(directory: &Path, frequency: f64) -> Vec<u8> {
    encode_audio(directory, frequency, 600)
}

fn encode_audio(directory: &Path, frequency: f64, buffers: i32) -> Vec<u8> {
    encode_audio_with_bitrate(directory, frequency, buffers, 128)
}

fn encode_audio_with_bitrate(
    directory: &Path,
    frequency: f64,
    buffers: i32,
    bitrate: i32,
) -> Vec<u8> {
    gst::init().unwrap();
    let path = directory.join("original-cc0.mp3");
    let pipeline = gst::Pipeline::new();
    let source = gst::ElementFactory::make("audiotestsrc")
        .property("num-buffers", buffers)
        .property("samplesperbuffer", 441_i32)
        .property("freq", frequency)
        .property("volume", 0.01_f64)
        .build()
        .unwrap();
    let convert = gst::ElementFactory::make("audioconvert").build().unwrap();
    let caps = gst::ElementFactory::make("capsfilter")
        .property(
            "caps",
            gst::Caps::builder("audio/x-raw")
                .field("rate", 44100_i32)
                .field("channels", 1_i32)
                .build(),
        )
        .build()
        .unwrap();
    let encoder = gst::ElementFactory::make("lamemp3enc")
        .property("bitrate", bitrate)
        .property("cbr", true)
        .build()
        .unwrap();
    let sink = gst::ElementFactory::make("filesink")
        .property("location", path.to_str().unwrap())
        .build()
        .unwrap();
    pipeline
        .add_many([&source, &convert, &caps, &encoder, &sink])
        .unwrap();
    gst::Element::link_many([&source, &convert, &caps, &encoder, &sink]).unwrap();
    pipeline.set_state(gst::State::Playing).unwrap();
    let eos = pipeline
        .bus()
        .unwrap()
        .timed_pop_filtered(
            gst::ClockTime::from_seconds(5),
            &[gst::MessageType::Eos, gst::MessageType::Error],
        )
        .is_some_and(|message| matches!(message.view(), gst::MessageView::Eos(_)));
    pipeline.set_state(gst::State::Null).unwrap();
    assert!(eos);
    let bytes = fs::read(&path).unwrap();
    fs::remove_file(path).unwrap();
    bytes
}

fn media_files(root: &Path) -> Vec<PathBuf> {
    let mut result = Vec::new();
    if !root.exists() {
        return result;
    }
    for entry in fs::read_dir(root).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            result.extend(media_files(&path));
        } else if path.file_name().is_some_and(|name| name == "media.bin") {
            result.push(path);
        }
    }
    result
}

fn run_phase(input: &Path, phase: &str, directory: &Path) -> PhaseReport {
    let log = fs::File::create(directory.join(format!("{phase}.log"))).unwrap();
    let mut command = Command::new(std::env::current_exe().unwrap());
    command
        .args([
            "--exact",
            SELECTOR,
            "--ignored",
            "--test-threads=1",
            "--nocapture",
        ])
        .env(PHASE_ENV, phase)
        .env(INPUT_ENV, input)
        .env("KARIN_AUDIO_CACHE_DIAGNOSTICS", "1")
        .env("XDG_CONFIG_HOME", directory.join("config"))
        .env("XDG_CACHE_HOME", directory.join("cache"))
        .env("XDG_DATA_HOME", directory.join("data"))
        .env("XDG_STATE_HOME", directory.join("state"))
        .stdout(Stdio::from(log.try_clone().unwrap()))
        .stderr(Stdio::from(log));
    if phase.starts_with("presence-") {
        command.env("GTK_A11Y", "test");
    }
    let mut child: Child = command.spawn().unwrap();
    let deadline = Instant::now() + Duration::from_secs(45);
    loop {
        if let Some(status) = child.try_wait().unwrap() {
            if !status.success() {
                retain_child_log(directory, phase);
                panic!("application phase {phase} failed; inspect its isolated captured log");
            }
            break;
        }
        if Instant::now() >= deadline {
            child.kill().unwrap();
            child.wait().unwrap();
            retain_child_log(directory, phase);
            panic!("application phase exceeded its bounded deadline");
        }
        thread::sleep(Duration::from_millis(5));
    }
    let log = fs::read_to_string(directory.join(format!("{phase}.log"))).unwrap();
    let diagnostics = log
        .lines()
        .filter(|line| line.starts_with("cache="))
        .collect::<Vec<_>>();
    assert!(
        !diagnostics.is_empty(),
        "each application phase must expose a safe cache outcome"
    );
    for line in diagnostics {
        let fields = line.split_whitespace().collect::<Vec<_>>();
        assert_eq!(
            fields.len(),
            3,
            "diagnostic contains only three finite fields"
        );
        assert!(matches!(
            fields[0],
            "cache=miss"
                | "cache=queued"
                | "cache=downloading"
                | "cache=downloaded"
                | "cache=write-confirmed"
                | "cache=hit"
                | "cache=stale"
                | "cache=checking"
                | "cache=not-cacheable"
        ));
        assert!(matches!(fields[1], "source=local" | "source=remote"));
        let reason = fields[2].strip_prefix("reason=").unwrap();
        assert!(!reason.is_empty() && reason.len() <= 64);
        assert!(
            reason
                .bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
        );
    }
    serde_json::from_slice(&fs::read(directory.join(format!("{phase}.json"))).unwrap()).unwrap()
}

#[test]
#[ignore = "requires isolated X11/D-Bus, xdotool, GStreamer MP3 plugins; launches the normal application factory in separate processes"]
fn native_audio_cache_application_process_restart() {
    if let Ok(phase) = std::env::var(PHASE_ENV) {
        let input: Input =
            serde_json::from_slice(&fs::read(std::env::var_os(INPUT_ENV).unwrap()).unwrap())
                .unwrap();
        if phase.starts_with("identity-") || phase.starts_with("presence-") {
            identity::run_child(&input, &phase);
            return;
        }
        if phase.starts_with("lifecycle-") {
            lifecycle::run_child(&input, &phase);
            return;
        }
        if phase.starts_with("completion-") {
            completion::run_child(&input, &phase);
            return;
        }
        application_child(&input, &phase);
        return;
    }
    if std::env::var_os("KARIN_TEST_CACHE_UI_ONLY").as_deref() == Some(std::ffi::OsStr::new("1")) {
        // Debug selection never writes the five-receipt/full-51 coverage set.
        // Child dispatch above must precede it so inherited selection cannot
        // recursively start another parent. Normal local/CI leaves it unset.
        eprintln!("Karin native cache fixture: scope=presence-only coverage=partial");
        identity::run_presence_only();
        return;
    }
    if let Ok(phase) = std::env::var("KARIN_TEST_COMPLETION_ONLY") {
        // Diagnostic selection never writes a full-coverage receipt. Normal
        // local/CI execution leaves this unset and runs every old/new phase.
        completion::run_parent_only(&phase);
        return;
    }
    let directory = Directory::new();
    for kind in ["config", "cache", "data", "state"] {
        fs::DirBuilder::new()
            .mode(0o700)
            .create(directory.0.join(kind))
            .unwrap();
    }
    let media = Arc::new(permitted_audio(&directory.0, 440.0));
    let replacement = Arc::new(permitted_audio(&directory.0, 880.0));
    assert_ne!(
        digest(&SHA256, &media).as_ref(),
        digest(&SHA256, &replacement).as_ref()
    );
    let server = OriginalServer::new(media.clone(), replacement.clone());
    let mut input = Input {
        directory: directory.0.clone(),
        origin: server.origin.clone(),
        sha256: digest(&SHA256, &media).as_ref().try_into().unwrap(),
        bytes: media.len() as u64,
        license: "CC0-1.0".into(),
    };
    let input_path = directory.0.join("original-source.json");
    fs::write(&input_path, serde_json::to_vec(&input).unwrap()).unwrap();
    let first = run_phase(&input_path, "first", &directory.0);
    assert_eq!(first.first_source, "remote-https");
    assert_eq!(first.replay_source.as_deref(), Some("cached-file"));
    let first_counts = server.counts();
    assert_eq!(first_counts.account, 1);
    assert_eq!(
        first_counts.media_gets, 2,
        "first play must use one native transfer and one independent background copy"
    );
    assert_eq!(first_counts.native_gets, 1);
    assert_eq!(first_counts.background_gets, 1);
    assert_eq!(first_counts.media_bytes, 2 * media.len() as u64);
    assert!(first_counts.media_heads >= 1);
    assert!(first_counts.media_not_modified >= 1);
    let audio_root = directory
        .0
        .join("cache")
        .join(crate::config::APP_ID)
        .join("audio");
    let files = media_files(&audio_root);
    assert_eq!(files.len(), 1);
    assert_original_file(&files[0], &input);
    let inode = fs::metadata(&files[0]).unwrap().ino();
    // A new signed wrapper is not itself a new audio version. The fresh
    // descriptor still identifies the same origin/path/encoding; the server
    // must positively confirm its strong ETag before any local replay.
    server.timestamp.fetch_add(1, Ordering::AcqRel);
    let restart = run_phase(&input_path, "restart", &directory.0);
    assert_ne!(
        first.pid, restart.pid,
        "this must be a real process restart"
    );
    assert_eq!(restart.first_source, "cached-file");
    let restart_counts = server.counts();
    assert_eq!(restart_counts.account, first_counts.account + 1);
    assert!(
        restart_counts.offers > first_counts.offers
            && restart_counts.descriptors > first_counts.descriptors
    );
    assert_eq!(
        restart_counts.media_gets, first_counts.media_gets,
        "restarting must not download cached audio"
    );
    assert_eq!(restart_counts.media_heads, first_counts.media_heads + 1);
    assert_eq!(
        restart_counts.media_not_modified,
        first_counts.media_not_modified + 1
    );
    assert_original_file(&files[0], &input);
    assert_eq!(
        fs::metadata(&files[0]).unwrap().ino(),
        inode,
        "replay must reuse the completed file"
    );
    server.deny.store(true, Ordering::Release);
    let denied = run_phase(&input_path, "denied", &directory.0);
    assert_eq!(denied.first_source, "none");
    let denied_counts = server.counts();
    assert_eq!(denied_counts.media_gets, first_counts.media_gets);
    assert_eq!(denied_counts.media_heads, restart_counts.media_heads);
    assert_eq!(
        denied_counts.media_not_modified,
        restart_counts.media_not_modified
    );
    assert_original_file(&files[0], &input);
    server.deny.store(false, Ordering::Release);
    fs::write(&files[0], b"damaged original cache bytes").unwrap();
    let repaired = run_phase(&input_path, "corrupt", &directory.0);
    assert_eq!(repaired.first_source, "remote-https");
    let repaired_files = media_files(&audio_root);
    assert_eq!(repaired_files.len(), 1);
    assert_original_file(&repaired_files[0], &input);
    let repaired_counts = server.counts();
    assert_eq!(
        repaired_counts.media_gets, 4,
        "corruption must fall back to native playback and a complete replacement copy"
    );
    server.changed.store(true, Ordering::Release);
    server.etag_revision.store(2, Ordering::Release);
    input.sha256 = digest(&SHA256, &replacement).as_ref().try_into().unwrap();
    input.bytes = replacement.len() as u64;
    fs::write(&input_path, serde_json::to_vec(&input).unwrap()).unwrap();
    let changed = run_phase(&input_path, "changed", &directory.0);
    assert_eq!(changed.first_source, "remote-https");
    let changed_files = media_files(&audio_root);
    assert_eq!(changed_files.len(), 1);
    assert_original_file(&changed_files[0], &input);
    let changed_counts = server.counts();
    assert_eq!(
        changed_counts.media_gets, 6,
        "changed ETag must fetch complete current bodies without mixing bytes"
    );
    assert_eq!(changed_counts.media_heads, repaired_counts.media_heads + 1);
    assert_eq!(
        changed_counts.media_not_modified,
        repaired_counts.media_not_modified
    );
    server.no_store.store(true, Ordering::Release);
    let no_store = run_phase(&input_path, "no-store", &directory.0);
    assert_eq!(no_store.first_source, "remote-https");
    assert!(
        media_files(&audio_root).is_empty(),
        "no-store revalidation must retire the previously reusable record"
    );
    let no_store_counts = server.counts();
    assert_eq!(no_store_counts.media_gets, 7);
    assert_eq!(no_store_counts.media_heads, changed_counts.media_heads + 1);
    assert_eq!(
        no_store_counts.media_not_modified,
        changed_counts.media_not_modified + 1,
        "even a matching 304 must obey its new no-store directive"
    );
    server.no_store.store(false, Ordering::Release);
    let restored = run_phase(&input_path, "restore", &directory.0);
    assert_eq!(restored.first_source, "remote-https");
    let restored_files = media_files(&audio_root);
    assert_eq!(restored_files.len(), 1);
    assert_original_file(&restored_files[0], &input);
    let restored_counts = server.counts();
    assert_eq!(restored_counts.media_gets, 9);
    assert_eq!(restored_counts.media_heads, no_store_counts.media_heads);
    // HEAD permits caching but announces a changed validator. The following
    // actual playback response alone withdraws storage, which must also retire
    // the old record rather than merely abandoning its replacement writer.
    server.etag_revision.store(3, Ordering::Release);
    server.get_only_no_store.store(true, Ordering::Release);
    let get_no_store = run_phase(&input_path, "get-no-store", &directory.0);
    assert_eq!(get_no_store.first_source, "remote-https");
    assert!(
        media_files(&audio_root).is_empty(),
        "the streamed GET no-store must remove the old completed record"
    );
    let get_no_store_counts = server.counts();
    assert_eq!(get_no_store_counts.media_gets, 11);
    assert_eq!(
        get_no_store_counts.media_heads,
        restored_counts.media_heads + 1
    );
    assert_eq!(
        get_no_store_counts.media_not_modified, restored_counts.media_not_modified,
        "HEAD must expose the changed allowed validator, not the GET no-store"
    );
    server.get_only_no_store.store(false, Ordering::Release);
    let restored_again = run_phase(&input_path, "restore-again", &directory.0);
    assert_eq!(restored_again.first_source, "remote-https");
    let restored_again_files = media_files(&audio_root);
    assert_eq!(restored_again_files.len(), 1);
    assert_original_file(&restored_again_files[0], &input);
    let restored_again_counts = server.counts();
    assert_eq!(restored_again_counts.media_gets, 13);
    assert_eq!(
        restored_again_counts.media_heads,
        get_no_store_counts.media_heads
    );
    let cleared = run_phase(&input_path, "clear", &directory.0);
    assert_eq!(cleared.first_source, "cached-file");
    assert!(cleared.clear_kept_playing);
    assert!(media_files(&audio_root).is_empty());
    let cleared_counts = server.counts();
    assert_eq!(
        cleared_counts.media_gets, 13,
        "clear of an active cached source must not reconnect"
    );
    assert_eq!(
        cleared_counts.media_not_modified,
        restored_again_counts.media_not_modified + 1
    );
    server.no_validator.store(true, Ordering::Release);
    let no_validator = run_phase(&input_path, "no-validator", &directory.0);
    assert_eq!(no_validator.first_source, "remote-https");
    assert_eq!(no_validator.replay_source.as_deref(), Some("remote-https"));
    let final_counts = server.counts();
    assert_eq!(
        final_counts.account, 11,
        "every application process must freshly validate its account"
    );
    assert_eq!(
        final_counts.offers, 13,
        "every selected playback must freshly check the resource"
    );
    assert_eq!(
        final_counts.descriptors, 12,
        "the denied resource must not reach descriptor/CDN delivery"
    );
    assert_eq!(final_counts.media_gets, 17);
    assert_eq!(
        final_counts.media_bytes,
        media.len() as u64 * 4 + input.bytes * 13
    );
    let mut receipt = json!({
        "scope":"original-audio-private-http-normal-application",
        "mechanism":"independent-full-response", "real_yandex_service":false,
        "account_checks":final_counts.account, "download_info_checks":final_counts.offers,
        "descriptor_checks":final_counts.descriptors, "media_gets":final_counts.media_gets,
        "native_gets":final_counts.native_gets, "background_gets":final_counts.background_gets,
        "media_heads":final_counts.media_heads, "media_not_modified":final_counts.media_not_modified,
        "media_bytes":final_counts.media_bytes, "original_bytes":media.len(), "changed_bytes":input.bytes,
        "payload_sha256":digest(&SHA256,&media).as_ref().iter().map(|byte|format!("{byte:02x}")).collect::<String>(),
        "changed_payload_sha256":input.sha256.iter().map(|byte|format!("{byte:02x}")).collect::<String>(),
        "cached_inode_unchanged_after_restart":true, "restart_signed_wrapper_rotated":true,
        "no_store_revalidation_removed_record":true, "no_store_get_removed_record":true
    });
    let phases = json!({"first":first,"restart":restart,"denied":denied,"corrupt":repaired,"changed":changed,"no_store":no_store,"restore":restored,"get_no_store":get_no_store,"restore_again":restored_again,"clear":cleared,"no_validator":no_validator});
    let wire = json!({"after_first":first_counts,"after_restart":restart_counts,"after_denial":denied_counts,"after_corruption":repaired_counts,"after_changed":changed_counts,"after_no_store":no_store_counts,"after_restore":restored_counts,"after_get_no_store":get_no_store_counts,"after_restore_again":restored_again_counts,"after_clear":cleared_counts,"after_no_validator":final_counts});
    receipt
        .as_object_mut()
        .unwrap()
        .extend(phases.as_object().unwrap().clone());
    receipt
        .as_object_mut()
        .unwrap()
        .extend(wire.as_object().unwrap().clone());
    if let Some(captures) = std::env::var_os("KARIN_TEST_CAPTURE_DIR") {
        fs::create_dir_all(&captures).unwrap();
        fs::write(
            PathBuf::from(captures).join("audio-cache-application-receipt.json"),
            serde_json::to_vec_pretty(&receipt).unwrap(),
        )
        .unwrap();
    }
    eprintln!(
        "Karin cache application: policy=private-http media-get-count={} media-bytes={} restart=local refusal=blocked corruption=online-repair changed=online-update no-store=retired get-no-store=retired restore=saved clear=playing no-validator=online-only",
        final_counts.media_gets, final_counts.media_bytes
    );
    lifecycle::run_parent();
    completion::run_parent();
    identity::run_parent();
}

fn source_name(kind: PlaybackSourceKind) -> &'static str {
    match kind {
        PlaybackSourceKind::None => "none",
        PlaybackSourceKind::LocalFile => "local-file",
        PlaybackSourceKind::RemoteHttps => "remote-https",
        PlaybackSourceKind::CachedFile => "cached-file",
    }
}

fn application_child(input: &Input, phase: &str) {
    assert!(matches!(
        phase,
        "first"
            | "restart"
            | "denied"
            | "corrupt"
            | "changed"
            | "restore"
            | "get-no-store"
            | "restore-again"
            | "clear"
            | "no-store"
            | "no-validator"
    ));
    gtk::init().unwrap();
    adw::init().unwrap();
    assert_eq!(input.license, "CC0-1.0");
    let settings = SettingsStore::for_application().unwrap();
    if phase == "first" {
        settings.save(&Preferences::default()).unwrap();
    }
    let cache_root = glib::user_cache_dir().join(crate::config::APP_ID);
    let budget = CacheBudget::new(
        cache_root.join("persistent"),
        cache_root.join("audio"),
        true,
        Preferences::default().cache_limit.bytes(),
    )
    .unwrap();
    let cache = Cache::new_with_budget(
        cache_root.join("persistent"),
        CachePolicy::default(),
        budget,
    )
    .unwrap();
    let backend = Backend::new(Some(TOKEN));
    let mut state = State::for_testing(
        settings,
        CredentialStore::with_backend(backend.clone()),
        Some(cache),
    );
    state.audio_root = Some(cache_root.join("audio"));
    let app = adw::Application::builder()
        .application_id("io.github.tracerxbrhd.Karin.CacheAcceptance")
        .flags(gio::ApplicationFlags::NON_UNIQUE)
        .build();
    app.register(gio::Cancellable::NONE).unwrap();
    let ui = crate::ui::build_with_music_pane(
        &app,
        crate::application::ConnectionService::new(crate::api::YandexApi::new().unwrap()),
        |app, window| {
            MusicPane::with_provider_state(
                app,
                window,
                Some(MusicService::for_test(&input.origin)),
                Arc::new(OfflineProvider),
                launch_system_browser,
                state,
            )
        },
    );
    ui.window.set_title(Some(TITLE));
    ui.window.set_default_size(900, 1000);
    ui.window.present();
    let this = &ui.music.controller;
    pump_until(|| this.model.borrow().account_valid && settled(this));
    assert_eq!(backend.loads.load(Ordering::Acquire), 1);
    assert!(this.persistence.borrow().values.cache_enabled);
    assert_eq!(
        this.persistence.borrow().values.cache_limit,
        CacheLimit::GiB2
    );
    assert!(
        this.persistence.borrow().audio_cache.is_some(),
        "the normal persistence factory must open the store"
    );
    assert!(
        this.persistence.borrow().settings.is_some() && this.persistence.borrow().manager.is_some()
    );
    assert_idle_wave_after_startup(this, true);
    this.set_fixture_resolver_for_test(StreamResolver::for_test(
        &input.origin,
        &input.origin,
        &input.origin,
    ));
    pointer(&ui.window, &this.widgets.nav_liked);
    pump_until(|| {
        this.model
            .borrow()
            .liked
            .as_ref()
            .is_some_and(|reply| reply.as_ref().is_ok_and(|page| page.items.len() == 1))
    });
    let row = this.widgets.library_rows.row_at_index(0).unwrap();
    pointer(&ui.window, &row);
    if phase == "denied" {
        pump_until(|| {
            !this.music_requested()
                && this.widgets.status.title().as_str() == "Не удалось получить источник аудио"
        });
        assert!(
            this.music_snapshot()
                .is_none_or(|snapshot| snapshot.state != PlaybackState::Playing)
        );
        close_child(&ui, this);
        write_phase(
            input,
            PhaseReport {
                phase: phase.into(),
                pid: std::process::id(),
                account_revalidated: true,
                cache_policy: "private-http".into(),
                first_source: "none".into(),
                replay_source: None,
                clear_kept_playing: false,
                default_limit_bytes: 2 * 1024 * 1024 * 1024,
            },
        );
        return;
    }
    wait_source(
        this,
        if matches!(
            phase,
            "first"
                | "corrupt"
                | "changed"
                | "restore"
                | "get-no-store"
                | "restore-again"
                | "no-store"
                | "no-validator"
        ) {
            PlaybackSourceKind::RemoteHttps
        } else {
            PlaybackSourceKind::CachedFile
        },
    );
    let first_source = source_name(this.music_snapshot().unwrap().source_kind).to_string();
    let mut replay_source = None;
    let mut clear_kept_playing = false;
    if matches!(
        phase,
        "first" | "corrupt" | "changed" | "restore" | "restore-again"
    ) {
        wait_publication(this, input);
    }
    if phase == "first" {
        assert!(row.grab_focus());
        key(&ui.window, "Return");
        wait_source(this, PlaybackSourceKind::CachedFile);
        replay_source = Some(source_name(this.music_snapshot().unwrap().source_kind).into());
    }
    if phase == "no-validator" {
        pump_until(|| this.cache_work_settled_for_test());
        assert!(
            media_files(
                &input
                    .directory
                    .join("cache")
                    .join(crate::config::APP_ID)
                    .join("audio")
            )
            .is_empty(),
            "no validator must prevent publishing reusable audio"
        );
        let serial = this.music_serial();
        assert!(row.grab_focus());
        key(&ui.window, "Return");
        pump_until(|| this.music_serial() > serial);
        wait_source(this, PlaybackSourceKind::RemoteHttps);
        replay_source = Some(source_name(this.music_snapshot().unwrap().source_kind).into());
        pump_until(|| this.cache_work_settled_for_test());
        assert!(
            media_files(
                &input
                    .directory
                    .join("cache")
                    .join(crate::config::APP_ID)
                    .join("audio")
            )
            .is_empty()
        );
    }
    if phase == "clear" {
        let before = this.music_snapshot().unwrap();
        this.present_preferences();
        let dialog = this
            .persistence
            .borrow()
            .view
            .as_ref()
            .unwrap()
            .dialog
            .clone();
        let clear = find_named(dialog.upcast_ref(), "preferences-cache-clear")
            .and_then(|widget| widget.downcast::<gtk::Button>().ok())
            .expect("native Clear control");
        let operation = this.persistence.borrow().cache_operation;
        let clicked = Rc::new(Cell::new(0));
        clear.connect_clicked({
            let clicked = clicked.clone();
            move |_| clicked.set(clicked.get() + 1)
        });
        // On GTK4.14 a mapped control can still be outside its scrolled
        // viewport. Use the same real-hit/scroll fixture as Preferences; a
        // toplevel-bounds coordinate is not evidence of a delivered click.
        crate::ui::preferences::click_native_for_test(&ui.window, &window_id(), &clear);
        assert_eq!(clicked.get(), 1, "one real native Clear click is required");
        pump_until(|| {
            this.persistence.borrow().cache_operation > operation
                && !this.persistence.borrow().cache_busy
                && !this.persistence.borrow().audio_purge_pending
        });
        let after = this.music_snapshot().unwrap();
        assert_eq!(after.state, PlaybackState::Playing);
        assert_eq!(after.generation, before.generation);
        assert!(this.model.borrow().account_valid);
        assert_eq!(this.model.borrow().queue.current().unwrap().id, "42");
        assert!(this.persistence.borrow().cache_retry.is_none());
        assert!(
            this.persistence
                .borrow()
                .audio_cache_stats
                .is_some_and(|stats| stats.entries == 0)
        );
        pump_until(|| {
            this.music_snapshot().is_some_and(|snapshot| {
                snapshot.state == PlaybackState::Playing
                    && snapshot.generation == before.generation
                    && snapshot.playing_time > after.playing_time + Duration::from_millis(40)
            })
        });
        clear_kept_playing = true;
        dialog.close();
    }
    // Observe the selected cache response's final result before AppClose can
    // legitimately cancel it. Refusal cases must exercise HTTP policy, rather
    // than pass because the process happened to exit before its worker ran.
    pump_until(|| this.cache_work_settled_for_test());
    close_child(&ui, this);
    write_phase(
        input,
        PhaseReport {
            phase: phase.into(),
            pid: std::process::id(),
            account_revalidated: true,
            cache_policy: "private-http".into(),
            first_source,
            replay_source,
            clear_kept_playing,
            default_limit_bytes: 2 * 1024 * 1024 * 1024,
        },
    );
}

fn wait_source(this: &Controller, kind: PlaybackSourceKind) {
    pump_until(|| {
        this.music_snapshot().is_some_and(|snapshot| {
            snapshot.state == PlaybackState::Playing
                && !snapshot.playing_time.is_zero()
                && snapshot.source_kind == kind
        })
    });
}
fn wait_publication(this: &Controller, input: &Input) {
    let (cache, _) = this.audio_cache_binding().unwrap();
    let published = Arc::new(AtomicBool::new(false));
    let observed = published.clone();
    let root = input
        .directory
        .join("cache")
        .join(crate::config::APP_ID)
        .join("audio");
    let expected_bytes = input.bytes;
    let expected_sha256 = input.sha256;
    let worker = thread::spawn(move || {
        let end = Instant::now() + Duration::from_secs(12);
        while Instant::now() < end {
            if cache.stats().is_ok_and(|stats| stats.entries == 1)
                && completed_media_matches(&root, expected_bytes, expected_sha256)
            {
                observed.store(true, Ordering::Release);
                return;
            }
            thread::sleep(Duration::from_millis(5));
        }
    });
    let end = Instant::now() + Duration::from_secs(15);
    while !published.load(Ordering::Acquire) {
        assert!(
            Instant::now() < end,
            "a complete authorized original response must publish its full file"
        );
        while glib::MainContext::default().pending() {
            glib::MainContext::default().iteration(false);
        }
        thread::sleep(Duration::from_millis(2));
    }
    worker.join().unwrap();
    pump_until(|| this.cache_work_settled_for_test());
}
fn completed_media_matches(root: &Path, expected_bytes: u64, expected_sha256: [u8; 32]) -> bool {
    let Ok(entries) = fs::read_dir(root) else {
        return false;
    };
    entries.filter_map(std::result::Result::ok).any(|entry| {
        let path = entry.path();
        if entry.file_name().as_encoded_bytes().starts_with(b".part-") {
            return false;
        }
        if path.is_dir() {
            return completed_media_matches(&path, expected_bytes, expected_sha256);
        }
        if entry.file_name() != "media.bin"
            || !path
                .parent()
                .is_some_and(|parent| parent.join("header").is_file())
        {
            return false;
        }
        fs::read(path).is_ok_and(|bytes| {
            bytes.len() as u64 == expected_bytes
                && digest(&SHA256, &bytes).as_ref() == expected_sha256
        })
    })
}
fn close_child(ui: &crate::ui::MainWindow, this: &Controller) {
    let stopped = this.music_cleanup_observer_for_test();
    this.close();
    ui.window.close();
    pump_until(|| {
        stopped()
            && !WorkFence::active()
            && this
                .persistence
                .borrow()
                .durable_work
                .load(Ordering::Acquire)
                == 0
    });
}
fn write_phase(input: &Input, report: PhaseReport) {
    fs::write(
        input.directory.join(format!("{}.json", report.phase)),
        serde_json::to_vec(&report).unwrap(),
    )
    .unwrap();
}
fn find_named(root: &gtk::Widget, name: &str) -> Option<gtk::Widget> {
    if root.widget_name() == name {
        return Some(root.clone());
    }
    let mut child = root.first_child();
    while let Some(widget) = child {
        child = widget.next_sibling();
        if let Some(found) = find_named(&widget, name) {
            return Some(found);
        }
    }
    None
}
fn window_id() -> String {
    let found = Command::new("xdotool")
        .args([
            "search",
            "--onlyvisible",
            "--pid",
            &std::process::id().to_string(),
            "--name",
            &format!("^{TITLE}$"),
        ])
        .output()
        .unwrap();
    assert!(found.status.success());
    String::from_utf8(found.stdout)
        .unwrap()
        .lines()
        .next()
        .unwrap()
        .to_owned()
}
fn pointer(window: &adw::ApplicationWindow, target: &impl IsA<gtk::Widget>) {
    let (x, y) = super::super::super::test_input::pointer(
        window,
        target,
        super::super::super::test_input::Target::Leading,
    );
    let widget = target.as_ref();
    if widget.native().and_then(|native| native.surface()) == window.surface() {
        let scale = f64::from(window.scale_factor());
        let (dx, dy) = window.surface_transform();
        let picked = window.pick(
            f64::from(x) / scale - dx,
            f64::from(y) / scale - dy,
            gtk::PickFlags::DEFAULT,
        );
        assert!(
            picked
                .as_ref()
                .is_some_and(|picked| picked == widget || picked.is_ancestor(widget)),
            "native fixture pointer target is covered: target={} picked={:?}",
            widget.type_().name(),
            picked.as_ref().map(|picked| picked.type_().name()),
        );
    }
    let id = window_id();
    let command = |args: Vec<String>| {
        assert!(
            Command::new("xdotool")
                .args(args)
                .status()
                .unwrap()
                .success()
        );
    };
    command(vec!["windowfocus".into(), "--sync".into(), id.clone()]);
    let query = |args: &[&str]| {
        let output = Command::new("xdotool").args(args).output().unwrap();
        assert!(output.status.success());
        String::from_utf8(output.stdout).unwrap()
    };
    let geometry = query(&["getwindowgeometry", "--shell", &id]);
    let position = query(&["getmouselocation", "--shell"]);
    let field = |text: &str, name: &str| {
        text.lines()
            .find_map(|line| line.strip_prefix(name))
            .unwrap()
            .parse::<i32>()
            .unwrap()
    };
    // xdotool's --sync can wait forever for a no-op relative move.
    // Repeated clicks at the same row could otherwise block this GTK
    // thread forever. Skip only movement already confirmed at the real root
    // coordinates; changed targets keep the original synchronized motion.
    if field(&position, "X=") != field(&geometry, "X=") + x
        || field(&position, "Y=") != field(&geometry, "Y=") + y
    {
        command(vec![
            "mousemove".into(),
            "--sync".into(),
            "--window".into(),
            id,
            x.to_string(),
            y.to_string(),
        ]);
    }
    command(vec!["click".into(), "1".into()]);
}
fn key(_window: &adw::ApplicationWindow, value: &str) {
    assert!(
        Command::new("xdotool")
            .args(["windowfocus", "--sync", &window_id()])
            .status()
            .unwrap()
            .success()
    );
    assert!(
        Command::new("xdotool")
            .args(["key", value])
            .status()
            .unwrap()
            .success()
    );
}

fn retain_child_log(directory: &Path, phase: &str) {
    if let Some(captures) = std::env::var_os("KARIN_TEST_CAPTURE_DIR") {
        let captures = PathBuf::from(captures);
        fs::create_dir_all(&captures).unwrap();
        fs::copy(
            directory.join(format!("{phase}.log")),
            captures.join(format!("audio-cache-application-{phase}.log")),
        )
        .unwrap();
    }
}

fn assert_original_file(path: &Path, input: &Input) {
    let bytes = fs::read(path).unwrap();
    assert_eq!(bytes.len() as u64, input.bytes);
    assert_eq!(digest(&SHA256, &bytes).as_ref(), input.sha256);
}

mod completion;
mod lifecycle;

mod identity;
